{
  "$schema": "./node_modules/@biomejs/biome/configuration_schema.json",
  "vcs": {
    "enabled": true,
    "clientKind": "git",
    "useIgnoreFile": true
  },
  "files": {
    "includes": [
      "**",
      "!**/node_modules",
      "!**/dist",
      "!**/coverage",
      "!**/storybook-static",
      "!src/types",
      "!src-tauri/target",
      "!src-tauri/gen"
    ]
  },
  "formatter": {
    "enabled": true,
    "indentStyle": "space",
    "indentWidth": 2,
    "lineWidth": 100
  },
  "javascript": {
    "formatter": {
      "quoteStyle": "single",
      "semicolons": "always",
      "trailingCommas": "all",
      "arrowParentheses": "always"
    }
  },
  "linter": {
    "enabled": true,
    "rules": {
      "recommended": true
    }
  },
  "assist": {
    "actions": {
      "source": {
        "organizeImports": "on"
      }
    }
  }
}

arguments.command:
cat missions/sessions/lint-baseline-cleanup/reviewer-6ee3e20d-804e-492b-a16d-4025f16ed2aa.jsonl | python3 -c "import json,sys
for line in sys.stdin:
    d=json.loads(line)
    msg=d.get('message',{})
    role=msg.get('role','?')
    content=msg.get('content','')
    if isinstance(content,list):
        parts=[]
        for c in content:
            t=c.get('type','?')
            if t=='text': parts.append('TEXT: '+c.get('text','')[:300])
            elif t=='toolCall': parts.append('CALL '+c.get('name','?')+': '+json.dumps(c.get('arguments',{}))[:200])
            elif t=='toolResult': parts.append('RESULT: '+json.dumps(c.get('content',''))[:200])
            elif t=='thinking': parts.append('THINK: '+c.get('thinking','')[:300])
            else: parts.append(t)
        content='\n  '.join(parts)
    print(f'[{role}] {str(content)[:500]}')
    print('---')
"

